<template><div class="app-container"><el-alert type="info" :closable="false" title="工作日计报，节假日以平台日历配置为准；连续漏报仅提醒，不限制业务权限。金额单位：元。"/>
<el-form inline><el-form-item label="企业"><el-select v-model="companyId" @change="load" filterable><el-option v-for="c in companies" :key="c.id" :label="c.company_name" :value="c.id"/></el-select></el-form-item><el-button @click="load">刷新</el-button></el-form>
<template v-if="rulesMode"><el-form label-width="140px"><el-form-item label="截止时间"><el-time-picker v-model="rule.cutoff" value-format="HH:mm:ss"/></el-form-item><el-form-item label="提前提醒分钟"><el-input-number v-model="rule.remindMinutes" :min="0" :max="240"/></el-form-item><el-form-item label="连续漏报提醒天数"><el-input-number v-model="rule.thresholdDays" :min="1" :max="366"/></el-form-item><el-form-item label="默认仅工作日"><el-switch v-model="rule.weekdaysOnly"/></el-form-item><el-button :loading="saving" @click="saveRule">保存规则</el-button><el-button @click="check">立即检查提醒</el-button></el-form><el-divider>企业计报起点</el-divider><el-date-picker v-model="startDate" value-format="YYYY-MM-DD"/><el-button @click="saveStart">保存所选企业开始日期</el-button><el-divider>节假日与调休覆盖</el-divider><el-date-picker v-model="calendar.date" value-format="YYYY-MM-DD"/><el-switch v-model="calendar.required" active-text="应报日" inactive-text="无需填报"/><el-input v-model="calendar.remark" placeholder="节假日或调休说明" maxlength="200" style="width:240px"/><el-button @click="saveCalendar">保存日历</el-button><el-table :data="calendarRows"><el-table-column prop="business_date" label="日期"/><el-table-column label="是否计报"><template #default="{row}">{{row.required_day?'应报':'无需填报'}}</template></el-table-column><el-table-column prop="remark" label="说明"/></el-table></template>
<template v-else><el-tabs v-model="tab"><el-tab-pane label="每日填报与历史" name="daily"><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD"/><el-button @click="page=1;load()">筛选</el-button><el-button type="primary" v-hasPermi="['biz:report:write']" @click="edit()">新增填报</el-button><el-table :data="rows" v-loading="loading"><el-table-column prop="output_date" label="业务日期"/><el-table-column prop="output_value" label="产值（元）"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column prop="remark" label="备注"/><el-table-column label="操作"><template #default="{row}"><template v-if="['DRAFT','RETURNED'].includes(row.status)"><el-button v-hasPermi="['biz:report:write']" link @click="edit(row)">修改</el-button><el-button v-hasPermi="['biz:report:write']" link type="primary" @click="submit(row)">提交</el-button></template><span v-else>只读</span></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="page" v-model:limit="size" @pagination="load"/></el-tab-pane>
<el-tab-pane label="漏报与补填" name="missing"><el-alert :title="`漏报 ${compliance.missingCount||0} 天，连续 ${compliance.consecutiveDays||0} 个应报工作日未报；截止 ${compliance.cutoff||'23:59'}，仅提醒。`" type="warning" :closable="false"/><el-table :data="(compliance.missingDates||[]).map(date=>({date}))"><el-table-column prop="date" label="漏报日期"/><el-table-column label="操作"><template #default="{row}"><el-button v-hasPermi="['biz:report:write']" link @click="backfill(row.date)">补填</el-button></template></el-table-column></el-table><el-divider>提醒记录（站内）</el-divider><el-table :data="reminders"><el-table-column prop="create_time" label="时间"/><el-table-column prop="content" label="提醒内容"/><el-table-column label="状态"><template #default="{row}">{{row.resolved?'已补齐':'待处理'}}</template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="月度产值核对" name="month"><el-date-picker v-model="month" type="month" value-format="YYYY-MM"/><el-button @click="loadMonth">查询月份</el-button><p>已提交/已确认 {{summary.submittedCount||0}} 条，合计 {{summary.totalValue||0}} 元；未提交 {{summary.draftCount||0}} 条；漏报 {{summary.missingDates?.length||0}} 天。月度状态：{{states[summary.status]||'待核对'}}</p><el-button v-hasPermi="['biz:report:review']" :disabled="summary.status==='CONFIRMED'" @click="reviewMonth(true)">确认月份</el-button><el-button v-hasPermi="['biz:report:review']" :disabled="summary.status==='CONFIRMED'" @click="reviewMonth(false)">退回修改</el-button><el-table :data="summary.rows||[]"><el-table-column prop="output_date" label="日期"/><el-table-column prop="output_value" label="产值（元）"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}}</template></el-table-column></el-table><el-divider>月度核对记录</el-divider><el-table :data="summary.audits||[]"><el-table-column prop="action" label="结果"/><el-table-column prop="record_count" label="明细数"/><el-table-column prop="total_value" label="合计（元）"/><el-table-column prop="opinion" label="意见"/><el-table-column prop="create_time" label="时间"/></el-table></el-tab-pane></el-tabs></template>
<el-dialog v-model="visible" title="每日业务产值" width="500px"><el-form label-width="100px"><el-form-item label="业务日期"><el-date-picker v-model="form.outputDate" value-format="YYYY-MM-DD" :disabled="!!form.id"/></el-form-item><el-form-item label="产值（元）"><el-input-number v-model="form.outputValue" :min="0" :precision="2"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button :loading="saving" type="primary" @click="save">保存草稿</el-button></template></el-dialog>
</div></template>
<script setup>
import {ref,computed,watch,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const route=useRoute(),rulesMode=computed(()=>route.path.endsWith('report-rules')),companies=ref([]),companyId=ref(),rows=ref([]),total=ref(0),page=ref(1),size=ref(20),range=ref([]),loading=ref(false),saving=ref(false),tab=ref('daily'),visible=ref(false),form=ref({}),compliance=ref({}),reminders=ref([]),month=ref(new Date().toISOString().slice(0,7)),summary=ref({}),rule=ref({}),calendar=ref({required:false}),calendarRows=ref([]),startDate=ref()
const states={DRAFT:'草稿',RETURNED:'退回待改',SUBMITTED:'已提交',CONFIRMED:'已确认',OPEN:'待核对'}
async function load(){if(!companyId.value)return;loading.value=true;try{if(rulesMode.value){const r=(await request({url:'/reports/config'})).data;rule.value={cutoff:r.rule.cutoff_time,remindMinutes:r.rule.remind_minutes,thresholdDays:r.rule.threshold_days,weekdaysOnly:!!r.rule.weekdays_only,version:r.rule.version};calendarRows.value=r.calendar}else{const params={companyId:companyId.value};const r=await request({url:'/reports',params:{...params,pageNum:page.value,pageSize:size.value,from:range.value?.[0],to:range.value?.[1]}});rows.value=r.data.rows;total.value=r.data.total;compliance.value=(await request({url:'/reports/compliance',params})).data;reminders.value=(await request({url:'/reports/reminders',params})).data;if(tab.value==='month')await loadMonth()}}finally{loading.value=false}}
function edit(row){form.value=row?{id:row.id,outputDate:String(row.output_date).slice(0,10),outputValue:Number(row.output_value),remark:row.remark,version:row.version}:{outputValue:0,remark:''};visible.value=true}
async function backfill(date){const r=await request({url:'/reports',params:{companyId:companyId.value,from:date,to:date}});if(r.data.rows.length)edit(r.data.rows[0]);else{edit();form.value.outputDate=date}}
async function save(){saving.value=true;try{await request({url:'/reports'+(form.value.id?'/'+form.value.id:''),method:form.value.id?'put':'post',data:{...form.value,companyId:companyId.value,unit:'元'}});visible.value=false;ElMessage.success('已保存，请提交后计入完成填报');await load()}finally{saving.value=false}}
async function submit(row){await ElMessageBox.confirm('提交后仅能经平台月度退回再修改，是否提交？');await request({url:`/reports/${row.id}/submit`,method:'post',data:{companyId:companyId.value,version:row.version}});await load()}
async function loadMonth(){if(companyId.value&&month.value)summary.value=(await request({url:'/reports/month',params:{companyId:companyId.value,month:month.value}})).data}
async function reviewMonth(confirm){const r=await ElMessageBox.prompt(confirm?'请输入月度确认意见':'请输入退回原因','月度核对',{inputPattern:/\S+/,inputErrorMessage:'意见必填'});await request({url:'/reports/month/review',method:'post',data:{companyId:companyId.value,month:month.value,confirm,version:summary.value.version,opinion:r.value}});await loadMonth();await load()}
async function saveRule(){await request({url:'/reports/config',method:'put',data:rule.value});ElMessage.success('规则已保存');await load()}
async function saveCalendar(){await request({url:'/reports/calendar',method:'put',data:calendar.value});await load()}
async function saveStart(){await request({url:'/reports/start-date',method:'put',data:{companyId:companyId.value,date:startDate.value}});ElMessage.success('计报起点已保存')}
async function check(){await request({url:'/reports/check',method:'post'});ElMessage.success('已执行站内提醒检查')}
watch(tab,()=>{if(tab.value==='month')loadMonth()});watch(rulesMode,()=>{visible.value=false;load()});onMounted(async()=>{companies.value=(await request({url:'/reports/companies'})).data;companyId.value=companies.value[0]?.id;await load()})
</script>
